# No.601-700  例文チャンク
DATA = {
"601": {"ex": "I tried to persuade my cat to get off the keyboard, but it just typed a resignation letter for me.", "tr": "キーボードから降りるよう猫を説得しようとしたら、猫は私の退職届を代わりに打ち込んでいた。"},
"602": {"ex": "It took three hours and a full slideshow to convince my grandma that the internet is not a physical box.", "tr": "インターネットは物理的な箱ではないと祖母に納得させるのに、三時間とスライド一式が必要だった。"},
"603": {"ex": "The motivational poster tried to inspire me, but the coffee machine breaking down inspired me far more.", "tr": "その啓発ポスターは私を奮起させようとしたが、コーヒーマシンの故障のほうがはるかに私を奮起させた。"},
"604": {"ex": "Nothing can discourage a toddler who has decided that the vegetable will not be eaten today.", "tr": "今日は野菜を食べないと決めた幼児を思いとどまらせられるものは何もない。"},
"605": {"ex": "They decided to promote the intern who accidentally deleted the wrong database and then fixed everything overnight.", "tr": "間違ってデータベースを消してから一晩で全部直したインターンを、彼らは昇進させることに決めた。"},
"606": {"ex": "【動】One good nap can boost your mood, your memory, and your ability to ignore urgent emails.<br>【名】The tiny compliment gave my confidence a boost that lasted until I read the next comment.", "tr": "【動】一度の良い昼寝は、気分も記憶力も、緊急メールを無視する能力も高めてくれる。<br>【名】その小さな褒め言葉は、次のコメントを読むまで続く自信の上昇を私に与えた。"},
"607": {"ex": "My weekend plans always mysteriously expand to fill every hour I promised to spend cleaning the house.", "tr": "週末の計画は、家の掃除に使うと約束した時間すべてを埋めるように、いつも不思議と拡大する。"},
"608": {"ex": "The meeting was supposed to extend by ten minutes, but somehow it swallowed my entire afternoon.", "tr": "会議はたった十分延長される予定だったのに、なぜか私の午後全体を飲み込んだ。"},
"609": {"ex": "Reading strange menus abroad did broaden my mind, mostly by teaching me what I never want to eat again.", "tr": "海外で変なメニューを読むことは確かに私の視野を広げた、主に二度と食べたくないものを教えることで。"},
"610": {"ex": "【動】Gossip tends to spread faster than any official announcement the company carefully prepares.<br>【名】The spread of the rumor was so wide that even people on other floors knew before I did.", "tr": "【動】うわさは、会社が慎重に準備するどんな公式発表よりも速く広がる傾向がある。<br>【名】そのうわさの広がりはあまりに広く、他の階の人でさえ私より先に知っていた。"},
"611": {"ex": "【名】He wore a bright yellow tie to the funeral and insisted it symbolized hope.<br>【動】If both teams tie again, the referee has threatened to send everyone home without dinner.", "tr": "【名】彼は葬式に真っ黄色のネクタイを着けてきて、それは希望の象徴だと言い張った。<br>【動】もし両チームがまた同点になれば、審判は全員を夕食抜きで帰らせると脅している。"},
"612": {"ex": "Please fasten your seatbelt, because my driving has been described as an unexpected theme park ride.", "tr": "シートベルトを締めてください、私の運転は予期せぬ遊園地のアトラクションと言われているので。"},
"613": {"ex": "【動】He promised to fix the leaking sink, and three weeks later the bucket underneath is still working perfectly.<br>【名】Borrowing money from a loan shark to pay another loan shark is quite an impressive fix.", "tr": "【動】彼は水漏れするシンクを修理すると約束したが、三週間経った今も下のバケツが完璧に機能している。<br>【名】別の高利貸しに払うため高利貸しから金を借りるとは、なかなか見事な窮地だ。"},
"614": {"ex": "It took me six hours to install the app that promised to save me five minutes every day.", "tr": "毎日五分節約できると謳うアプリをインストールするのに、私は六時間かかった。"},
"615": {"ex": "I tried to resist the free sample table, but my legs walked me back three separate times.", "tr": "無料試食コーナーに抵抗しようとしたが、私の足は三度も別々に私をそこへ連れ戻した。"},
"616": {"ex": "My dog will obey any command instantly, as long as a treat is clearly visible in my hand.", "tr": "うちの犬は、おやつが手にはっきり見えている限り、どんな命令にも即座に従う。"},
"617": {"ex": "The speaker knew exactly how to engage the audience: he promised free food at the very end.", "tr": "その講演者は聴衆を惹きつける方法を正確に知っていた、最後に無料の食べ物を約束したのだ。"},
"618": {"ex": "【動】I tried to walk quietly at night and managed to bump into every single piece of furniture we own.<br>【名】The bump on the road launched my coffee onto the ceiling with surprising accuracy.", "tr": "【動】夜に静かに歩こうとしたが、私は家のすべての家具に一つ残らずぶつかることに成功した。<br>【名】道路の凹凸は、驚くほどの正確さで私のコーヒーを天井へ打ち上げた。"},
"619": {"ex": "【動】Every time I try to bend down to tie my shoes, my back reminds me that I am no longer twenty.<br>【名】The road had such a sharp bend that even the GPS sounded genuinely worried.", "tr": "【動】靴ひもを結ぼうとかがむたび、私の腰はもう二十歳ではないと私に思い出させる。<br>【名】その道はあまりに急なカーブで、GPSでさえ本気で心配そうな声を出した。"},
"620": {"ex": "【動】My cat will hug my arm affectionately for exactly two seconds before biting it without warning.<br>【名】He gave the vending machine a gentle hug after it finally dropped the snack he paid for.", "tr": "【動】うちの猫はきっかり二秒間だけ私の腕を愛おしそうに抱きしめ、それから予告なく噛む。<br>【名】彼は、払った分のお菓子をやっと落とした自販機に、優しいハグをした。"},
"621": {"ex": "【動】The stranger continued to stare at my lunch as if he were writing a detailed review in his head.<br>【名】Her long stare told me the joke had landed somewhere very far from where I intended.", "tr": "【動】その見知らぬ人は、頭の中で詳細なレビューでも書くように、私の昼食をじっと見続けた。<br>【名】彼女の長い凝視は、その冗談が私の意図した場所からはるか遠くに着地したことを告げていた。"},
"622": {"ex": "【動】I like to gaze thoughtfully out the window, mostly to avoid the pile of dishes behind me.<br>【名】His romantic gaze was ruined slightly by the spinach clearly stuck in his front teeth.", "tr": "【動】私は物思わしげに窓の外を見つめるのが好きだ、主に背後の皿の山を避けるために。<br>【名】彼のロマンチックな視線は、前歯にはっきり挟まったほうれん草によって少し台無しになった。"},
"623": {"ex": "【動】I only planned to glance at my phone, and suddenly it was two hours and forty videos later.<br>【名】One quick glance at the bill was enough to make me quietly cancel dessert for everyone.", "tr": "【動】ちらりとスマホを見るだけのつもりが、気づけば二時間と四十本の動画が過ぎていた。<br>【名】伝票を一瞥しただけで、私は静かに全員分のデザートをキャンセルするのに十分だった。"},
"624": {"ex": "【名】I caught a glimpse of the surprise cake, so now everyone must pretend I looked genuinely shocked.<br>【動】If you glimpse the ending of a movie by accident, your brain will never let you forget it.", "tr": "【名】サプライズケーキがちらりと見えてしまったので、今や皆は私が本気で驚いたふりをせねばならない。<br>【動】もし映画の結末を偶然ちらりと見てしまえば、脳は決してそれを忘れさせてくれない。"},
"625": {"ex": "【動】I tried to stretch before exercising and pulled a muscle I did not even know I owned.<br>【名】After that long stretch of night shifts, I greeted the sunrise like a confused vampire.", "tr": "【動】運動前に伸ばそうとして、私は持っていることすら知らなかった筋肉を痛めた。<br>【名】夜勤が長く一続きに続いた後、私は困惑した吸血鬼のように日の出を迎えた。"},
"626": {"ex": "I managed to stumble over absolutely nothing in front of the one person I wanted to impress.", "tr": "印象づけたいと思っていた唯一の人の前で、私は完全に何もないところでつまずくことに成功した。"},
"627": {"ex": "【名】The press gathered outside the bakery, convinced the new limited-edition donut was breaking news.<br>【動】I had to press the elevator button eleven times before admitting it was clearly out of order.", "tr": "【名】報道機関はパン屋の外に集まり、新しい限定ドーナツが速報だと確信していた。<br>【動】明らかに故障中だと認めるまでに、私はエレベーターのボタンを十一回押さねばならなかった。"},
"628": {"ex": "【動】I had to drag my suitcase up four flights of stairs because the elevator chose that day to retire.<br>【名】This three-hour meeting about a single email was, frankly, an absolute drag.", "tr": "【動】エレベーターがその日に引退を選んだので、私はスーツケースを四階分引きずり上げねばならなかった。<br>【名】たった一通のメールについてのこの三時間の会議は、率直に言って完全に退屈なものだった。"},
"629": {"ex": "【動】I like to lean casually against walls, until I discover the wall was freshly painted.<br>【形】He proudly bought the lean cut of meat, then covered it in three types of cheese.", "tr": "【動】私は壁に何気なく寄りかかるのが好きだ、その壁が塗りたてだと気づくまでは。<br>【形】彼は誇らしげに脂肪の少ない肉を買い、それから三種類のチーズで覆った。"},
"630": {"ex": "【動】My cat will scratch the expensive new sofa exactly one minute after ignoring the costly scratching post.<br>【名】The tiny scratch on my new phone somehow feels more painful than any actual injury.", "tr": "【動】うちの猫は、高価な爪とぎを無視してきっかり一分後に、高い新しいソファをひっかく。<br>【名】新しいスマホの小さなひっかき傷は、どんな実際のけがよりもなぜか痛く感じる。"},
"631": {"ex": "【動】The actor tried to bow gracefully, tripped on the curtain, and received the biggest applause of the night.<br>【名】He gave such a deep bow of apology that his forehead nearly greeted the floor.", "tr": "【動】その俳優は優雅におじぎしようとしてカーテンにつまずき、その夜最大の拍手を受けた。<br>【名】彼はあまりに深い謝罪のおじぎをしたので、額が床に挨拶しかけた。"},
"632": {"ex": "【動】I tried to nod politely during the meeting while my brain quietly reviewed my grocery list.<br>【名】A single nod from the boss can mean approval, dismissal, or that he simply did not hear me.", "tr": "【動】会議中、私は礼儀正しくうなずこうとしたが、脳は静かに買い物リストを見直していた。<br>【名】上司の一度の会釈は、承認か、却下か、あるいは単に聞こえなかったことを意味しうる。"},
"633": {"ex": "【動】Every time I open my bank app, I sigh with the deep sorrow of a retired opera singer.<br>【名】Her long sigh across the office told the whole team the printer had broken down again.", "tr": "【動】銀行アプリを開くたび、私は引退したオペラ歌手のような深い悲しみでため息をつく。<br>【名】オフィス中に響く彼女の長いため息は、プリンターがまた壊れたことをチーム全員に告げた。"},
"634": {"ex": "【動】The moment someone starts to yawn in a quiet room, everyone else is instantly forced to join.<br>【名】My dramatic yawn during his story was not boredom, but it was very hard to explain that.", "tr": "【動】静かな部屋で誰かがあくびを始めた瞬間、他の全員が即座に加わることを強いられる。<br>【名】彼の話の途中での私の大げさなあくびは退屈ではなかったが、それを説明するのはとても難しかった。"},
"635": {"ex": "【動】I always manage to sneeze exactly when the photographer says the word cheese.<br>【名】One tiny sneeze in a silent library can echo like a dramatic movie explosion.", "tr": "【動】私はいつも、カメラマンがチーズと言うちょうどその瞬間にくしゃみをすることに成功する。<br>【名】静かな図書館での小さなくしゃみ一つは、映画の劇的な爆発のように響き渡ることがある。"},
"636": {"ex": "I decided to bury my old diary in the garden, and now a very confused dog guards it loyally.", "tr": "私は古い日記を庭に埋めることにしたが、今やとても困惑した犬が忠実にそれを守っている。"},
"637": {"ex": "He agreed to perform one magic trick at the party and accidentally set the tablecloth gently on fire.", "tr": "彼はパーティーで手品を一つ披露すると承知し、うっかりテーブルクロスをそっと燃やしてしまった。"},
"638": {"ex": "We decided to adopt a very small kitten, and it immediately adopted the entire house as its kingdom.", "tr": "私たちはとても小さな子猫を養子にすることにしたが、子猫は即座に家全体を自分の王国として引き取った。"},
"639": {"ex": "【動】My plan to escape the boring party quietly failed when I knocked over a very tall lamp.<br>【名】His daring escape from the meeting was foiled by a colleague blocking the door with questions.", "tr": "【動】退屈なパーティーからこっそり逃げる計画は、とても背の高いランプを倒したときに失敗した。<br>【名】会議からの彼の大胆な脱出は、質問でドアをふさぐ同僚によって阻止された。"},
"640": {"ex": "I tried to scatter the flower seeds evenly, and now one dramatic corner of my garden is a jungle.", "tr": "花の種を均等に散らそうとしたが、今や私の庭の劇的な一角がジャングルになっている。"},
"641": {"ex": "【動】I can fold a fitted sheet, but the result looks less like laundry and more like modern art.<br>【名】The map had so many folds that reopening it correctly became a serious family argument.", "tr": "【動】私はボックスシーツを折りたためるが、その結果は洗濯物というより現代美術に見える。<br>【名】その地図はあまりに折り目が多く、正しく開き直すことは深刻な家族の口論になった。"},
"642": {"ex": "I told him to hang his coat somewhere safe, and he hung it directly on the fire alarm.", "tr": "彼にコートをどこか安全な場所に掛けるよう言ったら、彼はそれを火災報知器に直接掛けた。"},
"643": {"ex": "【動】They promised to release the software update at midnight, and released our patience along with it.<br>【名】The release of the new game caused grown adults to request an urgent day off work.", "tr": "【動】彼らは真夜中にソフトウェア更新を発表すると約束し、それと一緒に私たちの忍耐も解放した。<br>【名】新しいゲームの発売は、いい大人たちに緊急の休暇を申請させた。"},
"644": {"ex": "【動】The clock chose to strike twelve loudly during the quietest, most romantic moment of the film.<br>【名】The workers went on strike, and the office plants finally got the silence they deserved.", "tr": "【動】その時計は、映画の最も静かでロマンチックな瞬間に、大きく十二時を打つことを選んだ。<br>【名】労働者たちはストライキに入り、オフィスの植物たちはついにふさわしい静けさを得た。"},
"645": {"ex": "【動】I tried to beat my brother at chess, and he beat me so quickly the pieces looked embarrassed.<br>【名】My heart skipped a beat when the boss walked in, then two more when he smiled at me.", "tr": "【動】チェスで弟に勝とうとしたが、彼はあまりに速く私を打ち負かし、駒が恥ずかしそうに見えた。<br>【名】上司が入ってきたとき私の心臓は一鼓動飛び、彼が私に微笑んだときさらに二回飛んだ。"},
"646": {"ex": "I bought an expensive case to protect my phone, then dropped the phone while admiring the case.", "tr": "スマホを守るため高価なケースを買い、それからケースに見とれている間にスマホを落とした。"},
"647": {"ex": "【動】I tried to twist the stubborn jar lid open and accidentally launched pickles across the kitchen.<br>【名】The movie had such a wild twist that the audience gasped louder than the actors on screen.", "tr": "【動】頑固な瓶のふたをひねって開けようとして、うっかりピクルスをキッチン中に打ち上げた。<br>【名】その映画はあまりに突飛なひねりがあり、観客は画面上の俳優より大きく息をのんだ。"},
"648": {"ex": "【動】I decided to skip breakfast to save time, and then spent that time thinking about breakfast.<br>【名】The child crossed the entire parking lot with a happy skip while adults trudged behind.", "tr": "【動】時間節約のため朝食を抜くことにし、それからその時間を朝食のことを考えて過ごした。<br>【名】その子は幸せそうなスキップで駐車場全体を横切り、大人たちは後ろをとぼとぼ歩いた。"},
"649": {"ex": "The documentary promised to expose a huge conspiracy but mostly exposed the narrator's dramatic breathing.", "tr": "そのドキュメンタリーは巨大な陰謀を暴露すると約束したが、主にナレーターの大げさな息づかいを暴露した。"},
"650": {"ex": "【動】I only had to stir the soup occasionally, so naturally I forgot and produced a solid black disk.<br>【名】One tiny stir of the spoon released a smell that stirred the whole office into the kitchen.", "tr": "【動】スープをたまにかき混ぜるだけでよかったので、当然私は忘れて固い黒い円盤を作り上げた。<br>【名】スプーンの一かきが放った匂いは、オフィス全体をキッチンへとかき立てた。"},
"651": {"ex": "【動】I tried to shake the ketchup bottle gently and repainted the entire ceiling in a single motion.<br>【名】The old bus gave such a violent shake that I briefly considered writing my last will.", "tr": "【動】ケチャップの瓶を優しく振ろうとして、私は一度の動作で天井全体を塗り直した。<br>【名】その古いバスはあまりに激しい揺れを与えたので、私は一瞬遺言を書こうかと考えた。"},
"652": {"ex": "【動】I spent an hour trying to polish my old shoes, which now shine brighter than my entire future.<br>【名】He applied so much polish to the table that guests kept checking their reflections during dinner.", "tr": "【動】古い靴を磨こうと一時間費やしたら、今やそれは私の将来全体より明るく輝いている。<br>【名】彼はテーブルに大量のつや出しを塗ったので、客は夕食中ずっと自分の姿を確認し続けた。"},
"653": {"ex": "I promised to attend the early morning meeting, and my body attended while my brain stayed in bed.", "tr": "早朝の会議に出席すると約束し、私の体は出席したが脳はベッドに留まっていた。"},
"654": {"ex": "My little brother loves to imitate my voice so perfectly that even our mother now blames me for everything.", "tr": "弟は私の声をあまりに完璧に真似るのが好きで、今や母でさえ何でも私のせいにする。"},
"655": {"ex": "【動】They asked me to conduct the meeting, so I nodded wisely and secretly hoped no one asked questions.<br>【名】His polite conduct at the party disappeared the moment the free dessert table was announced.", "tr": "【動】会議を進めるよう頼まれたので、私は賢そうにうなずき、誰も質問しないことを密かに願った。<br>【名】パーティーでの彼の礼儀正しい行いは、無料のデザートコーナーが発表された瞬間に消えた。"},
"656": {"ex": "【動】I continue to struggle with the self-checkout machine, which announces my failures at maximum volume.<br>【名】Getting out of a low, comfortable sofa is a daily struggle I am slowly learning to accept.", "tr": "【動】私は今もセルフレジと苦闘しており、それは私の失敗を最大音量で発表する。<br>【名】低くて快適なソファから立ち上がることは、私が少しずつ受け入れつつある日々の闘いだ。"},
"657": {"ex": "【動】I tried to burn a scented candle for relaxation and instead set off the smoke alarm dramatically.<br>【名】The tiny burn from the curling iron somehow hurt more than my entire disappointing week.", "tr": "【動】リラックスのため香り付きろうそくを燃やそうとしたが、代わりに劇的に煙探知機を鳴らした。<br>【名】ヘアアイロンの小さな火傷は、なぜか私のがっかりな一週間全体より痛かった。"},
"658": {"ex": "【動】He tried to cheat during the trivia game, but he confidently whispered every wrong answer.<br>【名】The card player was such an obvious cheat that even the dealer started laughing openly.", "tr": "【動】彼はクイズゲームで不正を働こうとしたが、自信満々に間違った答えばかりささやいた。<br>【名】そのカードプレイヤーはあまりに露骨な詐欺師で、ディーラーまで公然と笑い始めた。"},
"659": {"ex": "Everyone was encouraged to participate in the team activity, so I participated by loudly cheering from a safe chair.", "tr": "全員がチーム活動に参加するよう促されたので、私は安全な椅子から大声で応援することで参加した。"},
"660": {"ex": "According to my refrigerator, no leftovers exist, yet I clearly remember cooking enough for a small army.", "tr": "冷蔵庫によれば残り物は存在しないが、私は小さな軍隊分作った記憶がはっきりある。"},
"661": {"ex": "New problems always arise the exact moment I confidently announce that everything is finally under control.", "tr": "新たな問題は、すべてついに制御下にあると私が自信満々に宣言するちょうどその瞬間に、いつも生じる。"},
"662": {"ex": "Great ideas tend to occur to me at three in the morning, then vanish before I find a pen.", "tr": "素晴らしいアイデアは午前三時に私の心に浮かびがちで、それからペンを見つける前に消える。"},
"663": {"ex": "Any recipe that claims to be easy will secretly involve a tool I have never once owned.", "tr": "簡単だと主張するどんなレシピも、私が一度も持ったことのない道具をひそかに伴う。"},
"664": {"ex": "The simple form somehow decided to require three signatures, two stamps, and my complete loss of hope.", "tr": "その単純な用紙は、なぜか署名三つと印鑑二つ、そして私の希望の完全な喪失を必要とすることに決めた。"},
"665": {"ex": "My laziness at home has an ambitious counterpart at work who somehow finishes every project early.", "tr": "家での私の怠惰には、職場でなぜか全プロジェクトを早く終わらせる野心的な同等の存在がいる。"},
"666": {"ex": "The advent of the smart speaker means I now argue with a small cylinder about the weather forecast.", "tr": "スマートスピーカーの到来は、今や私が天気予報について小さな円柱と口論することを意味する。"},
"667": {"ex": "It takes remarkable discipline to maintain a serious face while your stomach loudly maintains its own opinion.", "tr": "腹が声高に自分の意見を主張している間、真剣な顔を維持するには並外れた自制心が要る。"},
"668": {"ex": "【形】This is absolutely the last cookie, I declared, reaching for what was clearly the next last cookie.<br>【副】I always save my hardest task for last, which is a polite way of saying never.<br>【動】I hoped the battery would last all day, but it lasted exactly until the important call began.<br>【名】He was the very last to leave the party and the very first to complain about the cleanup.", "tr": "【形】これは間違いなく最後のクッキーだと宣言しながら、私は明らかに次の最後のクッキーへ手を伸ばした。<br>【副】私はいつも一番難しい作業を最後にとっておくが、それは決してやらないという意味の丁寧な言い方だ。<br>【動】バッテリーが一日中もつことを願ったが、それは大事な電話が始まるちょうどその時まで続いた。<br>【名】彼はパーティーを去る一番最後の人で、片付けについて文句を言う一番最初の人だった。"},
"669": {"ex": "My phone will persist in reminding me about a birthday party that already ended two long weeks ago.", "tr": "私のスマホは、もう二週間も前に終わった誕生日パーティーについて、しつこく私に思い出させ続ける。"},
"670": {"ex": "The doctor promised to examine me quickly, then spent twenty minutes examining a spot I could not see.", "tr": "医者は素早く私を診察すると約束し、それから私に見えない箇所を二十分間検査した。"},
"671": {"ex": "【動】I joined the gym to gain muscle and mostly gained an impressive collection of unused water bottles.<br>【名】The financial report showed a small gain, which the manager celebrated like a lottery win.", "tr": "【動】筋肉を得るためジムに入会したが、主に未使用の水筒の見事なコレクションを手に入れた。<br>【名】財務報告はわずかな利益を示し、部長はそれを宝くじ当選のように祝った。"},
"672": {"ex": "To obtain one simple stamp, I had to visit three floors, two counters, and one very confusing hallway.", "tr": "たった一つの単純な印鑑を手に入れるため、私は三つの階、二つの窓口、そして非常に紛らわしい廊下を訪れねばならなかった。"},
"673": {"ex": "It took years to acquire the skill of appearing busy while doing absolutely nothing productive.", "tr": "生産的なことを全く何もせずに忙しそうに見せる技術を習得するのに、私は何年もかかった。"},
"674": {"ex": "【動】I always search for my glasses everywhere, only to find them sitting patiently on my own head.<br>【名】The search for the missing remote lasted longer than the movie we finally decided not to watch.", "tr": "【動】私はいつも眼鏡をあちこち探すが、結局それは自分の頭の上で辛抱強く座っているのを見つける。<br>【名】なくしたリモコンの捜索は、結局見ないことにした映画よりも長く続いた。"},
"675": {"ex": "There is nothing logical about buying a treadmill and then using it purely to hang wet laundry.", "tr": "ランニングマシンを買っておいて濡れた洗濯物を掛けるためだけに使うことには、論理的な点が何もない。"},
"676": {"ex": "I won a scholarship for my essay, then spent the money on snacks and one questionable inflatable chair.", "tr": "私は作文で奨学金を勝ち取り、それからそのお金をお菓子と一つの怪しい空気入れ椅子に使った。"},
"677": {"ex": "The furniture came with clear instructions, which is why I now own an artistic but useless wooden shape.", "tr": "その家具には明確な取扱説明書が付いてきたが、だからこそ私は今や芸術的だが役立たずの木の形を所有している。"},
"678": {"ex": "It can take me forty minutes to determine which streaming show to watch during a thirty-minute break.", "tr": "三十分の休憩の間にどの配信番組を見るか決定するのに、私は四十分かかることがある。"},
"679": {"ex": "After hours of heated debate, we all concluded that no one actually remembered why the meeting started.", "tr": "何時間もの白熱した議論の末、私たちは皆、なぜ会議が始まったのか実は誰も覚えていないと結論づけた。"},
"680": {"ex": "It is surprisingly hard to distinguish my serious work face from my quietly planning lunch face.", "tr": "私の真剣な仕事の顔と、静かに昼食を計画している顔を見分けるのは、意外にも難しい。"},
"681": {"ex": "My mom likes to classify all my hobbies into two neat categories: useless and slightly more useless.", "tr": "母は私の趣味すべてを、無駄とやや無駄という二つのきちんとした分類に分けるのが好きだ。"},
"682": {"ex": "【動】I always estimate that one small task will take five minutes, and reality politely laughs at me.<br>【名】The repair estimate was so high that I began to consider learning plumbing as a hobby.", "tr": "【動】私はいつも小さな作業一つが五分で済むと見積もり、現実は丁寧に私を笑う。<br>【名】修理の見積もりがあまりに高かったので、私は配管を趣味として学ぶことを検討し始めた。"},
"683": {"ex": "I spent the whole weekend trying to organize my closet, and now I cannot find a single thing.", "tr": "週末をまるごとクローゼットの整理に費やしたが、今や私は何一つ見つけられない。"},
"684": {"ex": "My phone somehow failed to recognize my face until I looked exactly as terrible as my morning self.", "tr": "私のスマホは、朝の自分そっくりのひどい顔をするまで、なぜか私の顔を認識できなかった。"},
"685": {"ex": "I suppose I could have read the manual first, but where exactly is the fun and suffering in that?", "tr": "先に説明書を読むこともできたと思うが、それのどこに楽しみと苦しみがあるというのか。"},
"686": {"ex": "Never assume the printer is working, because it can sense confidence and will immediately jam in protest.", "tr": "プリンターが動いていると決して思い込むな、それは自信を感じ取り、抗議して即座に紙詰まりを起こす。"},
"687": {"ex": "【名】My plant survives entirely on neglect, so any sudden care from me nearly sends it into shock.<br>【動】I try not to care what strangers think, but I still rehearsed that casual greeting eight times.", "tr": "【名】うちの植物は放置だけで生き延びているので、私からの突然の世話はそれをほぼショック状態に陥れる。<br>【動】見知らぬ人がどう思うか気にしないようにしているが、それでもあの何気ない挨拶を八回練習した。"},
"688": {"ex": "My cat will loudly approve of my cooking, right up until it sniffs the plate and dramatically walks away.", "tr": "うちの猫は私の料理を声高に賛成するが、それは皿を嗅いで劇的に立ち去るその瞬間までのことだ。"},
"689": {"ex": "【名】I received a notice about a fee, printed in a font clearly designed to be quietly ignored.<br>【動】People never notice my new haircut, but they instantly notice one tiny stain on my shirt.", "tr": "【名】私は料金についての通知を受け取ったが、それは明らかに静かに無視されるよう設計された書体で印刷されていた。<br>【動】人々は私の新しい髪型に決して気づかないが、シャツの小さなシミ一つには即座に気づく。"},
"690": {"ex": "I am fully aware that the diet starts tomorrow, which is precisely why today's cake tastes so free.", "tr": "ダイエットが明日から始まることは十分に自覚している、だからこそ今日のケーキはこんなに自由な味がする。"},
"691": {"ex": "I try to stay conscious during long meetings, but my eyelids clearly signed a different contract.", "tr": "長い会議の間、意識を保とうとするが、私のまぶたは明らかに別の契約書に署名した。"},
"692": {"ex": "My mother is deeply concerned that I am not eating well, so she sends enough food for six families.", "tr": "母は私が十分に食べていないことをひどく心配しており、六家族分の食料を送ってくる。"},
"693": {"ex": "【動】I tend to regard any recipe with more than five steps as a personal and unnecessary insult.<br>【名】He treats his plants with such regard that I sometimes suspect they eat better than I do.", "tr": "【動】私は五段階を超えるどんなレシピも、個人的で不必要な侮辱とみなす傾向がある。<br>【名】彼は植物をあまりに敬意をもって扱うので、時々それらが私よりいい食事をしていると疑う。"},
"694": {"ex": "I decided to commit fully to waking up early, and my alarm has been personally insulted every morning since.", "tr": "私は早起きに完全に専念することを決め、以来私の目覚まし時計は毎朝個人的に侮辱されている。"},
"695": {"ex": "【名】I have serious doubt that this all-in-one gadget can do even one of its promised jobs well.<br>【動】I doubt he actually read the report, judging by how confidently he praised the blank last page.", "tr": "【名】私は、このオールインワン機器が約束された仕事の一つでもうまくできるという点に深い疑いを持っている。<br>【動】空白の最終ページを自信満々に褒めた様子から判断して、彼が実際に報告書を読んだかを私は疑う。"},
"696": {"ex": "I can memorize every line of a silly song from childhood but forget a new password within ten seconds.", "tr": "私は子供時代のくだらない歌の全歌詞を暗記できるのに、新しいパスワードは十秒以内に忘れる。"},
"697": {"ex": "I decided to forgive my brother for eating my cake, right after he agreed to buy me two more.", "tr": "私は自分のケーキを食べた弟を許すことにした、彼がもう二つ買うと同意したそのすぐ後に。"},
"698": {"ex": "【動】The genie agreed to grant three wishes, then added so many conditions I nearly gave up on all of them.<br>【名】I applied for a research grant and received a very polite letter admiring my ambition instead.", "tr": "【動】そのランプの精は三つの願いを叶えると同意し、それからあまりに多くの条件を付けたので私はほぼ全部諦めかけた。<br>【名】私は研究助成金を申請し、代わりに私の野心を称える非常に丁寧な手紙を受け取った。"},
"699": {"ex": "【動】I can perfectly recall an embarrassing thing I said in school, yet forget why I walked into this room.<br>【名】The company issued a recall of the toaster, which had developed a worrying interest in fireworks.", "tr": "【動】学校で言った恥ずかしいことは完璧に思い出せるのに、なぜこの部屋に入ったのかは忘れる。<br>【名】その会社はトースターの回収を発表したが、それは花火への不穏な興味を抱くようになっていた。"},
"700": {"ex": "The weather outlook promised gentle sunshine, so naturally I planned a picnic during a surprise thunderstorm.", "tr": "天気の見通しは穏やかな日差しを約束したので、当然私は突然の雷雨の最中にピクニックを計画した。"},
}
